N = int(sys.argv[2]) if sys.argv[1:2] == ['--study'] and len(sys.argv) == 3 else None
assert N is not None or len(sys.argv) == 1, __doc__


def edit(path, old, new):
    if N is not None:
        return
    text = path.read_text(encoding='utf-8')
    assert text.count(old) == 1, (path.name, text.count(old), old[:90])
